{"command":"cd /workspace; cat > src/cli.rs <<'EOF'
//! Command line parsing for `hx`.
//!
//! This is a small, purpose-built argument parser that reproduces the
//! observable behaviour (help text, error messages, exit codes) of the
//! original tool's command line interface.

use std::ffi::{OsStr, OsString};
use std::os::unix::ffi::OsStrExt;

pub const APP_NAME: &str = "hx";
pub const APP_VERSION: &str = "0.7.0";

/// Identifiers for every argument understood by the program.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArgId {
    Cols,
    Len,
    Format,
    Color,
    Array,
    Func,
    Places,
    Prefix,
    Help,
    Version,
    InputFile,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Action {
    Set,
    Help,
    Version,
}

struct ArgDef {
    id: ArgId,
    short: Option<char>,
    long: Option<&'static str>,
    value_name: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
    action: Action,
    positional: bool,
}

impl ArgDef {
    fn takes_value(&self) -> bool {
        self.value_name.is_some()
    }

    /// Plain rendering of the argument, as used inside error messages.
    fn display(&self, required: Option<bool>) -> String {
        if self.positional {
            let name = self.value_name.unwrap_or("");
            if required.unwrap_or(false) {
                format!("<{}>", name)
            } else {
                format!("[{}]", name)
            }
        } else {
            let mut s = String::new();
            if let Some(l) = self.long {
                s.push_str("--");
                s.push_str(l);
            } else if let Some(c) = self.short {
                s.push('-');
                s.push(c);
            }
            if let Some(v) = self.value_name {
                s.push_str(" <");
                s.push_str(v);
                s.push('>');
            }
            s
        }
    }
}

/// Definition order matters: it drives suggestion ordering and usage output.
const ARGS: &[ArgDef] = &[
    ArgDef {
        id: ArgId::Cols,
        short: Some('c'),
        long: Some("cols"),
        value_name: Some("columns"),
        possible: None,
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Len,
        short: Some('l'),
        long: Some("len"),
        value_name: Some("len"),
        possible: None,
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Format,
        short: Some('f'),
        long: Some("format"),
        value_name: Some("format"),
        possible: Some(&["o", "x", "X", "b"]),
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Color,
        short: Some('t'),
        long: Some("color"),
        value_name: Some("color"),
        possible: Some(&["0", "1"]),
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Array,
        short: Some('a'),
        long: Some("array"),
        value_name: Some("array_format"),
        possible: Some(&["r", "c", "g", "p", "k", "j", "s", "f"]),
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Func,
        short: Some('u'),
        long: Some("func"),
        value_name: Some("func_length"),
        possible: None,
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Places,
        short: Some('p'),
        long: Some("places"),
        value_name: Some("func_places"),
        possible: None,
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::Prefix,
        short: Some('r'),
        long: Some("prefix"),
        value_name: Some("prefix"),
        possible: Some(&["0", "1"]),
        action: Action::Set,
        positional: false,
    },
    ArgDef {
        id: ArgId::InputFile,
        short: None,
        long: None,
        value_name: Some("INPUTFILE"),
        possible: None,
        action: Action::Set,
        positional: true,
    },
    ArgDef {
        id: ArgId::Help,
        short: Some('h'),
        long: Some("help"),
        value_name: None,
        possible: None,
        action: Action::Help,
        positional: false,
    },
    ArgDef {
        id: ArgId::Version,
        short: Some('V'),
        long: Some("version"),
        value_name: None,
        possible: None,
        action: Action::Version,
        positional: false,
    },
];

fn def(id: ArgId) -> &'static ArgDef {
    ARGS.iter().find(|a| a.id == id).expect("argument definition")
}

fn find_long(name: &str) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.long == Some(name))
}

fn find_short(c: char) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.short == Some(c))
}

fn positional() -> &'static ArgDef {
    ARGS.iter().find(|a| a.positional).expect("positional")
}

/// The successfully parsed command line.
#[derive(Debug, Default)]
pub struct Matches {
    values: Vec<(ArgId, String)>,
}

impl Matches {
    pub fn get(&self, id: ArgId) -> Option<&str> {
        self.values
            .iter()
            .find(|(i, _)| *i == id)
            .map(|(_, v)| v.as_str())
    }
}

/// Outcome of parsing that terminates the program before any real work.
pub enum Exit {
    /// Text destined for stdout, exit status 0 (help / version).
    Stdout(String),
    /// Text destined for stderr, exit status 2 (usage errors).
    Stderr(String),
}

// ---------------------------------------------------------------------------
// Jaro similarity (used for "did you mean" suggestions)
// ---------------------------------------------------------------------------

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();

    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }

    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);

    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;

    for (i, &ca) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && ca == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }

    let mut transpositions = 0usize;
    if matches != 0 {
        let mut bi = 0usize;
        for (i, &fa) in a_flags.iter().enumerate() {
            if fa {
                while bi < b_len {
                    let fb = b_flags[bi];
                    let cb = b[bi];
                    bi += 1;
                    if !fb {
                        continue;
                    }
                    if a[i] != cb {
                        transpositions += 1;
                    }
                    break;
                }
            }
        }
    }
    transpositions /= 2;

    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

/// Returns candidates sorted by ascending confidence (ties keep insertion order).
fn did_you_mean<'a, I>(v: &str, possible: I) -> Vec<String>
where
    I: IntoIterator<Item = &'a str>,
{
    let mut candidates: Vec<(f64, String)> = Vec::new();
    for pv in possible {
        let confidence = jaro(v, pv);
        if confidence > 0.7 {
            let pos = candidates
                .binary_search_by(|probe| {
                    if probe.0 > confidence {
                        std::cmp::Ordering::Greater
                    } else {
                        std::cmp::Ordering::Less
                    }
                })
                .unwrap_or_else(|e| e);
            candidates.insert(pos, (confidence, pv.to_owned()));
        }
    }
    candidates.into_iter().map(|(_, pv)| pv).collect()
}

// ---------------------------------------------------------------------------
// Error construction / rendering
// ---------------------------------------------------------------------------

const TAB: &str = "  ";

struct UsageError {
    message: String,
    suggested_arg: Option<String>,
    suggested_value: Option<String>,
    tips: Vec<String>,
    usage: Option<String>,
}

impl UsageError {
    fn new(message: String) -> Self {
        UsageError {
            message,
            suggested_arg: None,
            suggested_value: None,
            tips: Vec::new(),
            usage: None,
        }
    }

    fn render(&self) -> String {
        let mut out = String::new();
        out.push_str("error: ");
        out.push_str(&self.message);

        let mut suggested = false;
        if let Some(arg) = &self.suggested_arg {
            out.push('\n');
            if !suggested {
                out.push('\n');
                suggested = true;
            }
            out.push_str(&format!("{TAB}tip: a similar argument exists: '{arg}'"));
        }
        if let Some(val) = &self.suggested_value {
            out.push('\n');
            if !suggested {
                out.push('\n');
                suggested = true;
            }
            out.push_str(&format!("{TAB}tip: a similar value exists: '{val}'"));
        }
        if !self.tips.is_empty() {
            if !suggested {
                out.push('\n');
            }
            for tip in &self.tips {
                out.push_str(&format!("\n{TAB}tip: {tip}"));
            }
        }
        if let Some(usage) = &self.usage {
            out.push_str("\n\n");
            out.push_str(usage);
        }
        out.push_str("\n\nFor more information, try '--help'.\n");
        out
    }
}

enum ParseError {
    Usage(UsageError),
    Help,
    Version,
}

type ParseResult<T> = Result<T, ParseError>;

fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

// ---------------------------------------------------------------------------
// The parser
// ---------------------------------------------------------------------------

#[derive(Debug, PartialEq, Eq)]
enum ParseState {
    ValuesDone,
    Opt(ArgId),
}

struct Parser {
    bin_name: String,
    /// Arguments that have been fully processed, in order of appearance.
    matcher: Vec<(ArgId, Vec<OsString>)>,
    /// An argument whose values are still being collected.
    pending: Option<(ArgId, Vec<OsString>)>,
}

impl Parser {
    fn new(bin_name: String) -> Self {
        Parser {
            bin_name,
            matcher: Vec::new(),
            pending: None,
        }
    }

    // -- usage strings ----------------------------------------------------

    fn default_usage(&self) -> String {
        format!("Usage: {} [OPTIONS] [INPUTFILE]", self.bin_name)
    }

    fn smart_usage(&self, used: &[ArgId]) -> String {
        if used.is_empty() {
            return self.default_usage();
        }
        let mut s = format!("Usage: {} ", self.bin_name);
        let mut seen: Vec<ArgId> = Vec::new();
        let mut positional_used = false;
        for id in used {
            let d = def(*id);
            if d.positional {
                positional_used = true;
                continue;
            }
            if seen.contains(id) {
                continue;
            }
            seen.push(*id);
            s.push_str(&d.display(Some(true)));
            s.push(' ');
        }
        let pos = positional();
        s.push_str(&pos.display(Some(positional_used)));
        s.push(' ');
        s.trim_end().to_string()
    }

    fn used_ids(&self) -> Vec<ArgId> {
        self.matcher.iter().map(|(id, _)| *id).collect()
    }

    // -- errors -------------------------------------------------------------

    fn err_unknown_argument(
        &self,
        arg: String,
        did_you_mean: Option<String>,
        suggested_trailing_arg: bool,
        usage: String,
    ) -> ParseError {
        let mut e = UsageError::new(format!("unexpected argument '{arg}' found"));
        if suggested_trailing_arg {
            e.tips
                .push(format!("to pass '{arg}' as a value, use '-- {arg}'"));
        }
        e.usage = Some(usage);
        e.suggested_arg = did_you_mean;
        ParseError::Usage(e)
    }

    fn err_invalid_value(&self, d: &ArgDef, bad_val: &str) -> ParseError {
        let possible: Vec<&str> = d.possible.map(|p| p.to_vec()).unwrap_or_default();
        let suggestion = did_you_mean(bad_val, possible.iter().copied()).pop();
        let arg = d.display(None);
        let mut message = if bad_val.is_empty() {
            format!("a value is required for '{arg}' but none was supplied")
        } else {
            format!("invalid value '{bad_val}' for '{arg}'")
        };
        if !possible.is_empty() {
            message.push_str(&format!("\n{TAB}[possible values: "));
            for (i, v) in possible.iter().enumerate() {
                if i > 0 {
                    message.push_str(", ");
                }
                message.push_str(v);
            }
            message.push(']');
        }
        let mut e = UsageError::new(message);
        e.suggested_value = suggestion;
        ParseError::Usage(e)
    }

    fn err_argument_conflict(&self, d: &ArgDef) -> ParseError {
        let arg = d.display(None);
        let mut e = UsageError::new(format!(
            "the argument '{arg}' cannot be used multiple times"
        ));
        e.usage = Some(self.default_usage());
        ParseError::Usage(e)
    }

    fn err_too_many_values(&self, d: &ArgDef, val: String, used: &[ArgId]) -> ParseError {
        let arg = d.display(None);
        let mut e = UsageError::new(format!(
            "unexpected value '{val}' for '{arg}' found; no more were expected"
        ));
        e.usage = Some(self.smart_usage(used));
        ParseError::Usage(e)
    }

    fn err_invalid_utf8(&self) -> ParseError {
        let mut e = UsageError::new(
            "invalid UTF-8 was detected in one or more arguments".to_string(),
        );
        e.usage = Some(self.default_usage());
        ParseError::Usage(e)
    }

    // -- core state machine -------------------------------------------------

    fn resolve_pending(&mut self) -> ParseResult<()> {
        if let Some((id, vals)) = self.pending.take() {
            self.react(id, vals)?;
        }
        Ok(())
    }

    fn react(&mut self, id: ArgId, raw_vals: Vec<OsString>) -> ParseResult<()> {
        self.resolve_pending()?;
        let d = def(id);
        match d.action {
            Action::Set => {
                if raw_vals.is_empty() {
                    return Err(self.err_invalid_value(d, ""));
                }
                let existed = if let Some(pos) = self.matcher.iter().position(|(i, _)| *i == id) {
                    self.matcher.remove(pos);
                    true
                } else {
                    false
                };
                if existed {
                    return Err(self.err_argument_conflict(d));
                }
                self.matcher.push((id, Vec::new()));
                for raw in raw_vals {
                    let s = match raw.to_str() {
                        Some(s) => s.to_owned(),
                        None => return Err(self.err_invalid_utf8()),
                    };
                    if let Some(possible) = d.possible {
                        if !possible.iter().any(|p| *p == s) {
                            return Err(self.err_invalid_value(d, &s));
                        }
                    }
                    if let Some(entry) = self.matcher.iter_mut().find(|(i, _)| *i == id) {
                        entry.1.push(OsString::from(s));
                    }
                }
                Ok(())
            }
            Action::Help => Err(ParseError::Help),
            Action::Version => Err(ParseError::Version),
        }
    }

    /// Handles an option that takes a value, with an optional attached value.
    fn parse_opt_value(
        &mut self,
        attached: Option<&[u8]>,
        d: &ArgDef,
    ) -> ParseResult<ParseState> {
        if let Some(v) = attached {
            self.react(d.id, vec![OsStr::from_bytes(v).to_owned()])?;
            Ok(ParseState::ValuesDone)
        } else {
            self.resolve_pending()?;
            self.pending = Some((d.id, Vec::new()));
            Ok(ParseState::Opt(d.id))
        }
    }

    fn did_you_mean_error(&mut self, arg: &str, trailing_values: bool) -> ParseError {
        let longs: Vec<&str> = ARGS.iter().filter_map(|a| a.long).collect();
        let suggestion = did_you_mean(arg, longs.iter().copied()).pop();

        if let Some(name) = &suggestion {
            if let Some(d) = find_long(name) {
                if !self.matcher.iter().any(|(i, _)| *i == d.id) {
                    self.matcher.push((d.id, Vec::new()));
                }
            }
        }
        let suggestion = suggestion.map(|s| format!("--{s}"));

        let used = self.used_ids();
        let suggested_trailing_arg = suggestion.is_none() && !trailing_values;
        let usage = self.smart_usage(&used);
        self.err_unknown_argument(format!("--{arg}"), suggestion, suggested_trailing_arg, usage)
    }

    fn parse(&mut self, args: &[OsString]) -> ParseResult<()> {
        let mut parse_state = ParseState::ValuesDone;
        let mut pos_counter = 1usize;
        let mut trailing_values = false;

        let mut idx = 0usize;
        while idx < args.len() {
            let arg = &args[idx];
            idx += 1;
            let bytes = arg.as_bytes();

            if !trailing_values {
                if bytes == b"--" {
                    trailing_values = true;
                    continue;
                } else if bytes.len() > 2 && bytes.starts_with(b"--") {
                    // long argument
                    let remainder = &bytes[2..];
                    let (flag, value) = match remainder.iter().position(|b| *b == b'=') {
                        Some(p) => (&remainder[..p], Some(&remainder[p + 1..])),
                        None => (remainder, None),
                    };
                    let flag_str = match std::str::from_utf8(flag) {
                        Ok(s) => s,
                        Err(_) => {
                            let _ = self.resolve_pending();
                            return Err(self.did_you_mean_error(&lossy(flag), trailing_values));
                        }
                    };
                    match find_long(flag_str) {
                        Some(d) => {
                            if d.takes_value() {
                                parse_state = self.parse_opt_value(value, d)?;
                                continue;
                            } else if let Some(rest) = value {
                                let mut used = self.used_ids();
                                used.push(d.id);
                                let _ = self.resolve_pending();
                                return Err(self.err_too_many_values(d, lossy(rest), &used));
                            } else {
                                self.react(d.id, Vec::new())?;
                                parse_state = ParseState::ValuesDone;
                                continue;
                            }
                        }
                        None => {
                            let _ = self.resolve_pending();
                            return Err(self.did_you_mean_error(flag_str, trailing_values));
                        }
                    }
                } else if bytes.len() > 1 && bytes[0] == b'-' && bytes[1] != b'-' {
                    // short argument cluster
                    let remainder = &bytes[1..];
                    let (prefix, suffix) = match std::str::from_utf8(remainder) {
                        Ok(s) => (s, None),
                        Err(e) => {
                            let n = e.valid_up_to();
                            let p = std::str::from_utf8(&remainder[..n]).unwrap_or("");
                            (p, Some(&remainder[n..]))
                        }
                    };
                    let mut handled = false;
                    for (ci, c) in prefix.char_indices() {
                        match find_short(c) {
                            Some(d) => {
                                if !d.takes_value() {
                                    self.react(d.id, Vec::new())?;
                                    continue;
                                }
                                let after = &remainder[ci + c.len_utf8()..];
                                let val: Option<&[u8]> = if after.is_empty() { None } else { Some(after) };
                                let val = match val {
                                    Some(v) if v.first() == Some(&b'=') => Some(&v[1..]),
                                    other => other,
                                };
                                parse_state = self.parse_opt_value(val, d)?;
                                handled = true;
                                break;
                            }
                            None => {
                                let _ = self.resolve_pending();
                                let suggested_trailing_arg = !trailing_values;
                                let usage = self.default_usage();
                                return Err(self.err_unknown_argument(
                                    format!("-{c}"),
                                    None,
                                    suggested_trailing_arg,
                                    usage,
                                ));
                            }
                        }
                    }
                    if handled {
                        continue;
                    }
                    if let Some(suffix) = suffix {
                        let _ = self.resolve_pending();
                        let suggested_trailing_arg = !trailing_values;
                        let usage = self.default_usage();
                        return Err(self.err_unknown_argument(
                            format!("-{}", lossy(suffix)),
                            None,
                            suggested_trailing_arg,
                            usage,
                        ));
                    }
                    // Every character was a flag that was fully handled.
                    continue;
                }

                if let ParseState::Opt(id) = parse_state {
                    // Value for a previous option.
                    match &mut self.pending {
                        Some((pid, vals)) if *pid == id => vals.push(arg.clone()),
                        _ => {
                            self.pending = Some((id, vec![arg.clone()]));
                        }
                    }
                    parse_state = ParseState::ValuesDone;
                    continue;
                }
            }

            // Positional handling.
            if pos_counter == 1 {
                self.resolve_pending()?;
                self.pending = Some((ArgId::InputFile, vec![arg.clone()]));
                pos_counter += 1;
                parse_state = ParseState::ValuesDone;
            } else {
                let _ = self.resolve_pending();
                let is_long = bytes.starts_with(b"--") && bytes != b"--";
                let is_short = bytes.starts_with(b"-") && bytes != b"-" && !bytes.starts_with(b"--");
                let suggested_trailing_arg = !trailing_values && (is_long || is_short);
                let usage = self.default_usage();
                return Err(self.err_unknown_argument(
                    lossy(bytes),
                    None,
                    suggested_trailing_arg,
                    usage,
                ));
            }
        }

        self.resolve_pending()?;
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// Help / version text
// ---------------------------------------------------------------------------

fn help_text(bin_name: &str) -> String {
    format!(
        "Futuristic take on hexdump, made in Rust.


Usage: {bin_name} [OPTIONS] [INPUTFILE]

Arguments:
  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin

Options:
  -c, --cols <columns>        Set column length
  -l, --len <len>             Set <len> bytes to read
  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]
  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]
  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]
  -u, --func <func_length>    Set function wave length
  -p, --places <func_places>  Set function wave output decimal places
  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]
  -h, --help                  Print help
  -V, --version               Print version
"
    )
}

fn version_text() -> String {
    format!("{APP_NAME} {APP_VERSION}\n")
}

/// Derives the name shown in usage strings from `argv[0]`.
fn bin_name_from(argv0: Option<&OsString>) -> String {
    if let Some(a) = argv0 {
        let p = std::path::Path::new(a);
        if let Some(f) = p.file_name() {
            if let Some(s) = f.to_str() {
                return s.to_owned();
            }
        }
    }
    APP_NAME.to_owned()
}

/// Parses the given full argument vector (including `argv[0]`).
pub fn parse_from(argv: &[OsString]) -> Result<Matches, Exit> {
    let bin_name = bin_name_from(argv.first());
    let rest: &[OsString] = if argv.is_empty() { &[] } else { &argv[1..] };
    let mut parser = Parser::new(bin_name);
    match parser.parse(rest) {
        Ok(()) => {
            let mut m = Matches::default();
            for (id, vals) in parser.matcher {
                if let Some(v) = vals.into_iter().next() {
                    m.values.push((id, v.to_string_lossy().into_owned()));
                }
            }
            Ok(m)
        }
        Err(ParseError::Help) => Err(Exit::Stdout(help_text(&parser.bin_name))),
        Err(ParseError::Version) => Err(Exit::Stdout(version_text())),
        Err(ParseError::Usage(e)) => Err(Exit::Stderr(e.render())),
    }
}

/// Parses the process command line.
pub fn parse() -> Result<Matches, Exit> {
    let argv: Vec<OsString> = std::env::args_os().collect();
    parse_from(&argv)
}
