        Some(match s {
            "r" => ArrayLang::Rust,
            "c" => ArrayLang::C,
            "g" => ArrayLang::Go,
            "p" => ArrayLang::Python,
            "k" => ArrayLang::Kotlin,
            "j" => ArrayLang::Java,
            "s" => ArrayLang::Swift,
            "f" => ArrayLang::FSharp,
            _ => return None,
        })
    }

    fn header(self, len: usize) -> String {
        match self {
            ArrayLang::Rust => format!("let ARRAY: [u8; {}] = [", len),
            ArrayLang::C => format!("unsigned char ARRAY[{}] = {{", len),
            ArrayLang::Go => format!("a := [{}]byte{{", len),
            ArrayLang::Python => "a = [".to_string(),
            ArrayLang::Kotlin => "val a = byteArrayOf(".to_string(),
            ArrayLang::Java => "byte[] a = new byte[]{".to_string(),
            ArrayLang::Swift => "let a: [UInt8] = [".to_string(),
            ArrayLang::FSharp => "let a = [|".to_string(),
        }
    }

    fn footer(self) -> &'static str {
        match self {
            ArrayLang::Rust => "];",
            ArrayLang::C => "};",
            ArrayLang::Go => "}",
            ArrayLang::Python => "]",
            ArrayLang::Kotlin => ")",
            ArrayLang::Java => "};",
            ArrayLang::Swift => "]",
            ArrayLang::FSharp => "|]",
        }
    }

    fn element(self, b: u8) -> String {
        match self {
            ArrayLang::FSharp => format!("0x{:02x}uy", b),
            _ => format!("0x{:02x}", b),
        }
    }

    fn separator(self) -> &'static str {
        match self {
            ArrayLang::FSharp => "; ",
            _ => ", ",
        }
    }

    /// Whether the final element is also followed by a separator.
    fn trailing_separator(self) -> bool {
        matches!(self, ArrayLang::Go)
    }
}

/// Errors surfaced to `main`, which prints them as `error: <message>`.
#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    ParseInt(std::num::ParseIntError),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::Io(e) => write!(f, "{}", e),
            Error::ParseInt(e) => write!(f, "{}", e),
        }
    }
}

impl std::error::Error for Error {}

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Self {
        Error::Io(e)
    }
}

/// Parses an integer option, reporting the offending flag on failure.
fn parse_usize(value: &str, flag: &str) -> Result<usize, Error> {
    match value.parse::<usize>() {
        Ok(v) => Ok(v),
        Err(e) => {
            eprintln!("{} <integer> expected. {:?}", flag, e);
            Err(Error::ParseInt(e))
        }
    }
}

/// 256-colour index used for a given byte.
pub fn byte_color(b: u8) -> u8 {
    if b == 0 {
        22
    } else {
        b
    }
}

/// Textual rendering of a single octet.
pub fn format_octet(b: u8, format: Format, prefix: bool) -> String {
    match (format, prefix) {
        (Format::Octal, true) => format!("0o{:04o}", b),
        (Format::Octal, false) => format!("{:04o}", b),
        (Format::LowerHex, true) => format!("0x{:02x}", b),
        (Format::LowerHex, false) => format!("{:02x}", b),
        (Format::UpperHex, true) => format!("0x{:02X}", b),
        (Format::UpperHex, false) => format!("{:02X}", b),
        (Format::Binary, true) => format!("0b{:08b}", b),
        (Format::Binary, false) => format!("{:08b}", b),
    }
}

/// Character shown in the ASCII column for a byte.
pub fn ascii_char(b: u8) -> char {
    if (0x20..=0x7e).contains(&b) {
        b as char
    } else {
        '.'
    }
}

fn write_colored<W: Write>(out: &mut W, b: u8, text: &str, color: bool) {
    if color {
        let _ = write!(out, "\x1b[38;5;{}m{}\x1b[0m", byte_color(b), text);
    } else {
        let _ = write!(out, "{}", text);
    }
}

fn write_ascii_column<W: Write>(out: &mut W, row: &[u8], color: bool) {
    for &b in row {
        let mut buf = [0u8; 4];
        let s = ascii_char(b).encode_utf8(&mut buf);
        write_colored(out, b, s, color);
    }
}

/// Options controlling the hexdump rendering.
#[derive(Clone, Copy, Debug)]
pub struct DumpOptions {
    pub cols: usize,
    pub format: Format,
    pub prefix: bool,
    pub color: bool,
}

/// Writes the classic hexdump view: offset, octets, and ASCII column.
pub fn write_hexdump<W: Write>(out: &mut W, bytes: &[u8], opts: DumpOptions) {
    let cols = opts.cols;
    let _ = write!(out, "0x{:06x}: ", 0);
    let mut column = 0usize;
    let mut row: Vec<u8> = Vec::with_capacity(cols.min(4096));

    for (i, &b) in bytes.iter().enumerate() {
        let text = format_octet(b, opts.format, opts.prefix);
        write_colored(out, b, &text, opts.color);
        let _ = write!(out, " ");
        row.push(b);
        column += 1;
        if column >= cols {
            write_ascii_column(out, &row, opts.color);
            let _ = write!(out, "\n0x{:06x}: ", i + 1);
            row.clear();
            column = 0;
        }
    }

    finish_row(out, &row, cols, column, opts.color);
    let _ = writeln!(out, "   bytes: {}", bytes.len());
}

/// Pads a short final row so the ASCII column lines up, then writes it.
fn finish_row<W: Write>(out: &mut W, row: &[u8], cols: usize, column: usize, color: bool) {
    let missing = cols.wrapping_sub(column);
    let width = missing.wrapping_mul(OCTET_PAD_WIDTH);
    write_padding(out, width);
    write_ascii_column(out, row, color);
    let _ = writeln!(out);
}

fn write_padding<W: Write>(out: &mut W, width: usize) {
    let _ = write!(out, "{:>width$}", "", width = width);
}

/// Writes the bytes as a source code array literal.
pub fn write_array<W: Write>(out: &mut W, bytes: &[u8], cols: usize, lang: ArrayLang) {
    let _ = writeln!(out, "{}", lang.header(bytes.len()));
    let _ = write!(out, "    ");
    let mut column = 0usize;
    let last = bytes.len().saturating_sub(1);
    for (i, &b) in bytes.iter().enumerate() {
        let _ = write!(out, "{}", lang.element(b));
        if i != last || lang.trailing_separator() {
            let _ = write!(out, "{}", lang.separator());
        }
        column += 1;
        if column >= cols {
            let _ = write!(out, "\n    ");
            column = 0;
        }
    }
    let _ = writeln!(out, "\n{}", lang.footer());
}

/// Reads at most `limit` bytes (all of them when `limit` is zero).
fn read_input<R: Read>(reader: R, limit: usize) -> io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    if limit > 0 {
        reader.take(limit as u64).read_to_end(&mut buf)?;
    } else {
        let mut reader = reader;
        reader.read_to_end(&mut buf)?;
    }
    Ok(buf)
}

/// Decides whether to colourise output.
fn use_color(matches: &Matches) -> bool {
    match matches.get(ArgId::Color) {
        Some("1") => true,
        Some(_) => false,
        None => io::stdout().is_terminal() && std::env::var_os("NO_COLOR").is_none(),
    }
}

/// Runs the program with the parsed command line.
pub fn run(matches: &Matches) -> Result<(), Error> {
    if let Some(func) = matches.get(ArgId::Func) {
        let places = match matches.get(ArgId::Places) {
            Some(p) => parse_usize(p, "-p, --places")?,
            None => DEFAULT_PLACES,
        };
        let len = parse_usize(func, "-u, --func")?;
        function_output::output_function(len, places);
        return Ok(());
    }

    let reader: Box<dyn Read> = match matches.get(ArgId::InputFile) {
        Some(path) => Box::new(File::open(path)?),
        None => Box::new(io::stdin()),
    };

    let cols = match matches.get(ArgId::Cols) {
        Some(c) => parse_usize(c, "-c, --cols")?,
        None => DEFAULT_COLS,
    };
    let len = match matches.get(ArgId::Len) {
        Some(l) => parse_usize(l, "-l, --len")?,
        None => 0,
    };

    let bytes = read_input(reader, len)?;

    let stdout = io::stdout();
    let mut out = stdout.lock();

    if let Some(lang) = matches.get(ArgId::Array).and_then(ArrayLang::from_flag) {
        write_array(&mut out, &bytes, cols, lang);
        return Ok(());
    }

    let opts = DumpOptions {
        cols,
        format: matches
            .get(ArgId::Format)
            .map(Format::from_flag)
            .unwrap_or(Format::LowerHex),
        prefix: matches.get(ArgId::Prefix) != Some("0"),
        color: use_color(matches),
    };
    write_hexdump(&mut out, &bytes, opts);
    Ok(())
}
