//! Output of a sine "wave" of values, used by the `-u/--func` option.
//!
//! The wave consists of `len` samples taken from the first quarter of a sine
//! period, i.e. the values rise monotonically from `0` towards (but never
//! reaching) `1`.  Every sample is printed with a fixed number of decimal
//! places and terminated by a comma; ten samples are placed on each line.
//!
//! Example (`len = 5`, `places = 4`):
//!
//! ```text
//! 0.0000,0.3090,0.5878,0.8090,0.9511,
//! ```

use std::f64::consts::FRAC_PI_2;

/// Number of samples printed per line.
pub const VALUES_PER_LINE: usize = 10;

/// A quarter sine wave with a given number of samples.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Wave {
    /// Number of samples to produce.
    pub len: usize,
    /// Decimal places used when rendering each sample.
    pub places: usize,
}

impl Wave {
    /// Creates a wave of `len` samples rendered with `places` decimals.
    pub fn new(len: usize, places: usize) -> Wave {
        Wave { len, places }
    }

    /// Returns the `i`-th sample: `sin((i / len) * (pi / 2))`.
    ///
    /// The division is performed first so that the argument to `sin` is the
    /// normalised position within the quarter period scaled to `[0, pi/2)`.
    pub fn sample(&self, i: usize) -> f64 {
        ((i as f64 / self.len as f64) * FRAC_PI_2).sin()
    }

    /// Iterates over all samples of the wave.
    pub fn samples(&self) -> impl Iterator<Item = f64> + '_ {
        (0..self.len).map(move |i| self.sample(i))
    }

    /// Renders the whole wave as a single string, exactly as `write` prints
    /// it (useful for testing).
    pub fn render(&self) -> String {
        let mut out = String::new();
        let mut column = 0usize;
        for value in self.samples() {
            out.push_str(&format!("{:.*},", self.places, value));
            column += 1;
            if column >= VALUES_PER_LINE {
                out.push('\n');
                column = 0;
            }
        }
        out.push('\n');
        out
    }

    /// Prints the wave to standard output.
    pub fn write(&self) {
        let mut column = 0usize;
        for i in 0..self.len {
            let value = self.sample(i);
            let text: String = format!("{:.*}", self.places, value);
            print!("{},", text);
            column += 1;
            if column >= VALUES_PER_LINE {
                println!();
                column = 0;
            }
        }
        println!();
    }
}

/// Prints `len` samples of the quarter sine wave with `places` decimals.
pub fn output_function(len: usize, places: usize) {
    Wave::new(len, places).write();
}
